import Foundation

/// The web's label maps, loaded from the bundled strings.json (generated by `npm run api:catalog`
/// from src/lib/format.ts, never edited by hand). Unknown keys fall back to the raw value, as the
/// web does (`LABELS[key] ?? key`).
public struct Labels: Sendable {
    public struct Tagged: Decodable, Sendable, Equatable {
        public let label: String
        /// `success`, `warning`, `muted`, or `error`.
        public let variant: String
    }

    public struct TimeZoneOption: Decodable, Sendable, Equatable {
        public let value: String
        public let label: String
    }

    private struct Raw: Decodable {
        let offeringKind: [String: String]
        let paymentRule: [String: String]
        let paymentPurpose: [String: String]
        let weekday: [String]
        let bookingStatus: [String: String]
        let rosterStatus: [String: Tagged]
        let rosterPayment: [String: String]
        let timeZones: [TimeZoneOption]
    }

    private let raw: Raw

    public static let shared: Labels = {
        guard let url = resourceURL,
              let data = try? Data(contentsOf: url),
              let labels = try? Labels(json: data) else { fatalError("VamoKit's strings.json is missing or invalid; run npm run api:catalog") }
        return labels
    }()

    /// The bundled strings.json (also read by tests for the formatter vectors).
    static var resourceURL: URL? { Bundle.module.url(forResource: "strings", withExtension: "json") }

    init(json: Data) throws {
        struct File: Decodable { let labels: Raw }
        raw = try JSONDecoder().decode(File.self, from: json).labels
    }

    public func offeringKind(_ key: String) -> String { raw.offeringKind[key] ?? key }
    public func paymentRule(_ key: String) -> String { raw.paymentRule[key] ?? key }
    public func paymentPurpose(_ key: String) -> String { raw.paymentPurpose[key] ?? key }
    /// A player's booking status on Home ("Booked", "Finish payment", …).
    public func bookingStatus(_ key: String) -> String { raw.bookingStatus[key] ?? key }
    /// A booking on the coach's roster, with the badge variant.
    public func rosterStatus(_ key: String) -> Tagged { raw.rosterStatus[key] ?? Tagged(label: key, variant: "muted") }
    /// "" means show nothing (status `none`).
    public func rosterPayment(_ key: String) -> String { raw.rosterPayment[key] ?? "" }
    /// Sun…Sat, indexed 0–6 like JavaScript's getDay().
    public var weekdays: [String] { raw.weekday }
    public var timeZones: [TimeZoneOption] { raw.timeZones }
}
